Definition REBAL_STACK : Z := 32.

Definition rebal_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (ns' : NS) (lo : Z) (X : list Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (ibW lo (bv_unsigned sp) X) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ ANSR m' ns' X /\ ACONST m'.

Section Rebal.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m0 : mem) (h lo : Z) (X : list Z) (j8 : list byte).
  Hypothesis HC : aceil <= lo.
  Hypothesis LOSP : lo + REBAL_STACK <= bv_unsigned sp.
  Hypothesis HR : 0 <= h < 2^64.
  Hypothesis AC0 : ACONST m0.

  Definition rb_ctx (m : mem) (ns : NS) : Prop :=
    ANSR m ns X /\ munch (ibW lo (bv_unsigned sp) X) m0 m /\ wmono asegs m0 m /\ mem_inv asegs m
    /\ stk asegs m lo (bv_unsigned sp + -32)
    /\ rw_cells asegs m (bv_unsigned sp + -32) [CB 8 j8; C8 s1; C8 s0; C8 ra].

  #[local] Abbreviation POST ns' := (rebal_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns' lo X m0).

  Ltac open_ctx CTX := destruct CTX as (NSR1 & MU & WM & MI & ST & FR).
  Ltac close_ctx := split; [fast_eassumption| split; [fast_eassumption| split; [fast_eassumption| split; [fast_eassumption| split; fast_eassumption]]]].
  Ltac rb_pre :=
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
    pose proof aceil_facts as (AF1 & AF2 & AF3); unfold REBAL_STACK in LOSP.
