  (* [comment removed for export] *)
  Lemma rb_L_sc_h : forall m ns ns' (q : Z) (x1 t2 s0x s1x a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
    rb_ctx m ns ->
    (set_parent ns h q ≫= (λ ns1, set_color ns1 q BLACK ≫= (λ ns2, rb_end ns2 h))) = Some ns' ->
    0 <= q < 2^64 ->
    evt asegs (POST ns')
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp (Z_to_bv 64 2147450880) (Z_to_bv 64 (Z.shiftr h 3)) t2 s0x s1x
               (Z_to_bv 64 h) (Z_to_bv 64 q) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
