  (* [comment removed for export] *)
  Lemma rb_L_rotL_tail : forall m ns ns4 ns5 ns6 ns' (q gpv gpp gppl : Z) (x1 s0x s1x a5 a6 t6 : word),
    rb_ctx m ns ->
    (set_left ns q gpv ≫= (λ ns3, set_parent ns3 gpv q)) = Some ns4 ->
    (set_parent ns4 q gpp ≫= (λ ns5, ub_set_child ns5 h gpp gppl gpv q)) = Some ns5 ->
    set_color ns5 q BLACK = Some ns6 -> rb_end ns6 h = Some ns' ->
    q ∈ X -> gpv ∈ X -> gpp ∈ X ->
    0 <= q < 2^64 -> 0 <= gpv < 2^64 -> 0 <= gpp < 2^64 -> 0 <= gppl < 2^64 ->
    evt asegs (POST ns')
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp (Z_to_bv 64 2147450880) (Z_to_bv 64 (Z.shiftr h 3))
               (Z_to_bv 64 (Z.shiftr (gpp + 8) 3 + 2147450880)) s0x s1x
               (Z_to_bv 64 h) (Z_to_bv 64 q) (Z_to_bv 64 gpv) (Z_to_bv 64 (gpp + 8)) (Z_to_bv 64 (q + 8)) a5 a6 (Z_to_bv 64 gpp)
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
               (Z_to_bv 64 (Z.shiftr gpv 3 + 2147450880)) (Z_to_bv 64 gppl) (Z_to_bv 64 (Z.shiftr (q + 8) 3 + 2147450880)) t6)
