  (* [comment removed for export] *)
  Lemma rb_L_rotR_tail : forall m ns ns4 ns5 ns6 ns' (q gpv gpp gppl : Z) (x1 s0x s1x a4 a6 t6 : word),
    rb_ctx m ns ->
    (set_right ns q gpv ≫= (λ ns3, set_parent ns3 gpv q)) = Some ns4 ->
