Scheme kc__5 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.

  (* [comment removed for export] *)
  Lemma rb_L_final : forall m ns ns' (p pp gpv gpl : Z) (x1 s0x s1x a5 a6 a7 t4 t6 : word),
    rb_ctx m ns ->
    (rb_final ns h p pp gpv gpl ≫= (λ ns2, rb_end ns2 h)) = Some ns' ->
    p ∈ X -> pp ∈ X -> gpv ∈ X ->
    0 <= p < 2^64 -> 0 <= pp < 2^64 -> 0 <= gpv < 2^64 -> 0 <= gpl < 2^64 ->
    evt asegs (POST ns')
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp (Z_to_bv 64 2147450880) (Z_to_bv 64 (Z.shiftr h 3))
               (Z_to_bv 64 (Z.shiftr pp 3 + 2147450880)) s0x s1x
               (Z_to_bv 64 h) (Z_to_bv 64 p) (Z_to_bv 64 gpv) (Z_to_bv 64 pp) (Z_to_bv 64 (gpv + 8)) a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
               (Z_to_bv 64 (Z.shiftr (gpv + 8) 3 + 2147450880)) t4 (Z_to_bv 64 gpl) t6)
